    // For this example, it's hardcoded for simplicity.




    try {




        // Replace 'reference_field' with the actual name of your reference field
        var refField = g_form.getDisplayBox('caller_id');
        var refField2 = g_form.getControl('state');


        if (refField) {
            // Set the background color to yellow
            refField.style.backgroundColor = 'yellow';
			 refField2.style.backgroundColor = 'yellow';
        }
